const D = { hue: 210, energy: .6, speed: 1, density: .5, scale: 1, x: .5, y: .84, bulk: 1, limb: 1, visor: .6, seed: 0, pose: 'auto', style: 'noir', act: 'spacewalk' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const s = u * 0.0016 * P.scale;
const bt = K.beat * P.speed;
const sb = ((bt % 1) + 1) % 1;
const am = .78 + .3 * Math.sin(K.t * .29 + fr(6) * 6);
const eAmp = P.energy * (.55 + .6 * K.intensity) * am;
const kick = Math.min(1, K.pulse * (.5 + .5 * K.intensity) + A.bass * .75);
S.rms = (S.rms || 0) * .85 + (A.rms || 0) * .15;
S.tre = (S.tre || 0) * .8 + (A.treble || 0) * .2;
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

if (S.seedUsed !== P.seed || !S.star) {
  S.seedUsed = P.seed;
  S.star = []; for (let i = 0; i < 22; i++) S.star.push({ a: fr(i) * 6.283, r: .5 + fr(i + 30) * .85, w: .2 + fr(i + 60) * .7, o: fr(i + 90) * 6.283, sz: .6 + fr(i + 120) * 1.5 });
}

const ACTS = {
  spacewalk: ['float','idle','float','salute','float','dance','float','idle'],
  moondance: ['dance','dance','idle','dance','salute','dance','dance','idle'],
  mission: ['idle','salute','dance','float','idle','dance','salute','float'] };
let pose = P.pose;
if (pose === 'auto') pose = (ACTS[P.act] || ACTS.spacewalk)[((K.section % 8) + 8) % 8];

// ---- global slow drift: guarantees 8s silhouette displacement (beats aliasing) ----
const gSway = Math.sin(K.t * .36 + fr(2) * 6) * 24 + Math.sin(K.t * .19 + fr(4) * 6) * 12;
const gBob = Math.sin(K.t * .5 + fr(8) * 6) * 9;
const gTilt = Math.sin(K.t * .22 + fr(5) * 6) * .05;

// ---- kinematics (beat-derived) ----
const hang = Math.pow(Math.max(0, Math.sin(sb * Math.PI)), .55);   // low-g hangtime
const step = ((Math.floor(bt) % 2) + 2) % 2;
let hip = 0, bob = 0, tilt = 0, headB = 0, headT = 0, spin = 0;
let aLu = -.35, aLf = .5, aRu = .35, aRf = -.5;
let lLu = -.12, lLf = .2, lRu = .12, lRf = -.2;   // leg upper/lower angles
const swing = Math.sin(bt * Math.PI) * eAmp;

if (pose === 'idle') {
  hip = Math.sin(bt * Math.PI / 2) * 9 * eAmp;
  bob = -hang * 8 * eAmp - kick * 3;
  tilt = Math.sin(K.t * .55) * .045 + hip * .002;
  headT = -tilt * 1.2 + Math.sin(K.t * .7) * .05;
  headB = Math.sin(bt * Math.PI + .5) * 3 * eAmp;
  aLu = -.4 + swing * .16; aLf = .55 - swing * .1;
  aRu = .4 - swing * .16; aRf = -.55 + swing * .1;
  lLu = -.1 + swing * .1; lRu = .1 - swing * .1;
} else if (pose === 'dance') {
  hip = Math.sin(bt * Math.PI) * 24 * eAmp;
  bob = -(hang * 22 + kick * 8) * eAmp - S.rms * 18 * P.energy;
  tilt = Math.sin(bt * Math.PI) * .14 * eAmp;
  headB = Math.sin(bt * Math.PI * 2 + .3) * 5 * eAmp - kick * 3;
  headT = -tilt;
  const alt = step ? 1 : -1;
  aLu = -.55 + alt * (1.4 + kick) * eAmp; aLf = .4 + swing * .7;
  aRu = .55 - alt * (1.4 + kick) * eAmp; aRf = -.4 - swing * .7;
  lLu = -.15 - alt * .5 * hang; lLf = .25 + alt * .4 * hang;
  lRu = .15 + alt * .5 * hang; lRf = -.25 - alt * .4 * hang;
} else if (pose === 'salute') {
  hip = Math.sin(bt * Math.PI / 2) * 8 * eAmp;
  bob = -hang * 6 * eAmp;
  tilt = .05;
  headT = -.08; headB = Math.sin(bt * Math.PI) * 2;
  aRu = -1.15; aRf = -1.35 + Math.sin(bt * Math.PI * 2) * .15 * eAmp;   // right hand to helmet
  aLu = .35 + swing * .12; aLf = -.55;
  lLu = -.1; lRu = .1;
} else { // float — zero-g slow tumble, limbs drift
  spin = Math.sin(K.t * .4 + fr(3) * 6) * .18 + gTilt * 1.5;
  bob = Math.sin(K.t * .8) * 12 - 6;
  hip = Math.sin(K.t * .7) * 8;
  headT = Math.sin(K.t * .6) * .12;
  headB = Math.sin(bt * Math.PI) * 3;
  aLu = -.6 + Math.sin(K.t * 1.1) * .5; aLf = .7 + Math.sin(K.t * .9) * .3;
  aRu = .6 - Math.sin(K.t * 1.1 + 1) * .5; aRf = -.7 - Math.sin(K.t * .9 + 1) * .3;
  lLu = -.35 + Math.sin(K.t * 1.3) * .35; lLf = .3 + Math.sin(K.t) * .25;
  lRu = .35 - Math.sin(K.t * 1.3 + 1) * .35; lRf = -.3 - Math.sin(K.t + 1) * .25;
}

hip += gSway * .5; bob += gBob; tilt += gTilt;

const st = ['noir','blueprint','chrome','riso'].indexOf(P.style) >= 0 ? P.style : 'noir';
const H = ((P.hue % 360) + 360) % 360;
const BK = P.bulk, LB = P.limb;
// light direction (upper-left) for chiaroscuro
const lx = -.42, ly = -.62;

// ---------- chiaroscuro / style primitives ----------
function shade(cx, cy, w, h, br) {
  if (st === 'noir') {
    noStroke();
    fill(H, 8, br * .5); ellipse(cx, cy, w, h);                                  // base / shadow body
    fill(H, 5, Math.min(100, br + 34), 92); ellipse(cx + lx * w * .22, cy + ly * h * .22, w * .74, h * .74); // lit crescent
    fill(H, 3, Math.min(100, br + 55), 80); ellipse(cx + lx * w * .3, cy + ly * h * .3, w * .34, h * .34);    // specular
    fill(H, 30, br * .28, 46); ellipse(cx - lx * w * .26, cy - ly * h * .26, w * .55, h * .5);                // core shadow far side
  } else if (st === 'blueprint') {
    noFill(); stroke((H + 6) % 360, 70, 100, 82); strokeWeight(1.6 * s);
    ellipse(cx, cy, w, h);
    stroke((H + 6) % 360, 55, 100, 34); strokeWeight(1 * s);
    line(cx - w / 2, cy, cx + w / 2, cy); ellipse(cx, cy, w * .58, h);
    noStroke();
  } else if (st === 'chrome') {
    noStroke();
    for (let g = 0; g < 5; g++) { const f = g / 4; fill((H + 10) % 360, 22 - f * 14, 24 + f * 66); ellipse(cx, cy + (f - .5) * h * .5, w * (1 - Math.abs(f - .55) * .5), h * .2); }
    fill(H, 12, 30); ellipse(cx, cy, w, h);
    for (let g = 0; g < 6; g++) { const f = g / 5; fill(0, 0, 100, 10 + f * f * 40); ellipse(cx + lx * w * .2, cy - h * .3 + f * h * .55, w * (.7 - f * .5), h * .09); }
    fill(0, 0, 100, 85); ellipse(cx + lx * w * .28, cy + ly * h * .3, w * .12, h * .12);
  } else { // riso
    noStroke();
    fill((H + 175) % 360, 74, 88, 60); ellipse(cx - 4 * s, cy, w, h);
    fill(H, 78, 92, 66); ellipse(cx + 3 * s, cy + 2 * s, w, h);
    fill(H, 20, 16, 55); ellipse(cx, cy, w * .9, h * .9);
    fill(0, 0, 100, 40); ellipse(cx + lx * w * .25, cy + ly * h * .25, w * .3, h * .3);
  }
}
function tube(x1, y1, x2, y2, w) {
  strokeCap(ROUND);
  if (st === 'blueprint') { stroke((H + 6) % 360, 65, 100, 78); strokeWeight(w); line(x1, y1, x2, y2); stroke((H + 6) % 360, 50, 100, 30); strokeWeight(w * .35); line(x1, y1, x2, y2); noStroke(); return; }
  if (st === 'riso') {
    stroke((H + 175) % 360, 74, 88, 60); strokeWeight(w); line(x1 - 4 * s, y1, x2 - 4 * s, y2);
    stroke(H, 78, 90, 66); strokeWeight(w); line(x1 + 3 * s, y1 + 2 * s, x2 + 3 * s, y2 + 2 * s);
    stroke(H, 20, 16, 55); strokeWeight(w * .8); line(x1, y1, x2, y2); noStroke(); return;
  }
  if (st === 'chrome') { stroke(H, 12, 26); strokeWeight(w); line(x1, y1, x2, y2); stroke(0, 0, 100, 55); strokeWeight(w * .28); line(x1 + lx * w * .2, y1, x2 + lx * w * .2, y2); noStroke(); return; }
  // noir: dark tube + lit edge
  stroke(H, 8, 30); strokeWeight(w); line(x1, y1, x2, y2);
  stroke(H, 5, 96, 88); strokeWeight(w * .42); line(x1 + lx * w * .24, y1 + ly * 1 * s, x2 + lx * w * .24, y2 + ly * 1 * s);
  noStroke();
}

const ax = P.x * width + hip * s;
const ay = P.y * height + bob * s;

// ground shadow (faint / absent when floating)
noStroke(); fill(0, 0, 0, pose === 'float' ? 8 : 26);
ellipse(P.x * width, P.y * height + 8 * s, (86 + Math.abs(hip) * .7) * s * BK, 15 * s);

push();
translate(ax, ay);
rotate(tilt + spin);

const pelvY = -96, shldY = -178, headCY = -252, footY = 2;
// ---- legs (two-seg) ----
function leg(hx0, uAng, fAng, sgn) {
  const kx = hx0 + Math.sin(uAng) * 46 * LB * s, ky = pelvY * s + Math.cos(uAng) * 46 * LB * s;
  const fx = kx + Math.sin(uAng + fAng * sgn) * 44 * LB * s, fyy = ky + Math.cos(uAng + fAng * sgn) * 44 * LB * s;
  tube(hx0, pelvY * s, kx, ky, 20 * BK * s);
  tube(kx, ky, fx, fyy, 16 * BK * s);
  // boot
  shade(fx + sgn * 4 * s, fyy + 6 * s, 30 * BK * s, 20 * s, 62);
}
leg(-16 * s, lLu, lLf, 1);
leg(16 * s, lRu, lRf, -1);

// ---- backpack (behind torso) ----
shade(-2 * s, (shldY + 44) * s, 74 * BK * s, 108 * s, 55);

// ---- torso / suit ----
shade(0, (shldY + 46) * s, 96 * BK * s, 118 * s, 74);
// chest control panel
if (st !== 'blueprint') {
  push(); translate(-2 * s, (shldY + 40) * s);
  noStroke(); fill(H, 15, st === 'noir' ? 22 : 30); rectMode(CENTER); rect(0, 0, 40 * BK * s, 46 * s, 5 * s);
  const lit = .5 + .5 * Math.sin(bt * Math.PI * 2);
  fill(120, 80, 60 + lit * 40); rect(-9 * s, -12 * s, 6 * s, 6 * s, 1 * s);
  fill(30, 85, 70 + kick * 30); rect(0, -12 * s, 6 * s, 6 * s, 1 * s);
  fill(0, 85, 55 + (1 - lit) * 40); rect(9 * s, -12 * s, 6 * s, 6 * s, 1 * s);
  fill(200, 40, 85, 70); rect(0, 6 * s, 26 * BK * s, 4 * s, 2 * s); rect(0, 14 * s, 20 * BK * s, 4 * s, 2 * s);
  pop();
} else {
  noFill(); stroke((H + 6) % 360, 60, 100, 60); strokeWeight(1.2 * s); rectMode(CENTER); rect(-2 * s, (shldY + 40) * s, 40 * BK * s, 46 * s); rectMode(CORNER); noStroke();
}
// suit segment rings
if (st === 'noir' || st === 'chrome') { noFill(); stroke(H, 10, st === 'noir' ? 20 : 40, 55); strokeWeight(2 * s); for (let i = 0; i < 3; i++) arc(0, (shldY + 30 + i * 20) * s, 88 * BK * s, 30 * s, .15, Math.PI - .15); noStroke(); }

// ---- arms (two-seg) ----
function arm(sx, uAng, fAng, sgn) {
  const ux = sx + Math.sin(uAng) * 44 * LB * s, uy = (shldY + 6) * s + Math.cos(uAng) * 44 * LB * s;
  const hx = ux + Math.sin(uAng + fAng * sgn) * 42 * LB * s, hy = uy + Math.cos(uAng + fAng * sgn) * 42 * LB * s;
  tube(sx, (shldY + 6) * s, ux, uy, 17 * BK * s);
  tube(ux, uy, hx, hy, 14 * BK * s);
  shade(hx, hy, 22 * BK * s, 22 * BK * s, 66);   // glove
}
arm(-40 * BK * s, aLu, aLf, 1);
arm(40 * BK * s, aRu, aRf, -1);

// ---- helmet ----
push();
translate(headB * s, headCY * s + headB * .3 * s);
rotate(headT);
const HR = 62 * BK;
// helmet shell
shade(0, 0, HR * 2 * s, HR * 2 * s, 80);
// visor (dark, reflective)
push();
if (st === 'blueprint') {
  noFill(); stroke((H + 6) % 360, 70, 100, 82); strokeWeight(1.6 * s); ellipse(0, 4 * s, HR * 1.5 * s, HR * 1.35 * s);
  stroke((H + 6) % 360, 50, 100, 30); strokeWeight(1 * s); line(-HR * .7 * s, 4 * s, HR * .7 * s, 4 * s); line(0, 4 * s - HR * .65 * s, 0, 4 * s + HR * .65 * s);
  noStroke();
} else {
  noStroke();
  // visor glass
  fill(210, 60, 8 + P.visor * 6); ellipse(0, 4 * s, HR * 1.5 * s, HR * 1.35 * s);
  // reflected sun/horizon glow
  const sunH = (30 + Math.sin(K.t * .3) * 30 + 360) % 360;
  fill(sunH, 70, 92, 55 + 35 * P.visor); ellipse(-HR * .34 * s, -HR * .28 * s, HR * .5 * s, HR * .36 * s);
  fill(190, 45, 88, 40 * P.visor); rect(-HR * .55 * s, HR * .3 * s, HR * 1.1 * s, HR * .28 * s);
  // sweeping specular streak (moves with drift -> motion)
  const sx2 = Math.sin(K.t * .6) * HR * .4 * s;
  fill(0, 0, 100, 60 + 30 * kick); ellipse(sx2, -HR * .1 * s, HR * .16 * s, HR * .9 * s);
  // visor rim highlight
  noFill(); stroke(0, 0, 100, 50); strokeWeight(2 * s); arc(0, 4 * s, HR * 1.5 * s, HR * 1.35 * s, Math.PI * 1.05, Math.PI * 1.75); noStroke();
}
pop();
pop(); // helmet

pop(); // figure

// ---- starfield / drifting debris ----
const nStar = Math.max(0, Math.floor(3 + P.density * 18));
blendMode(ADD); noStroke();
for (let i = 0; i < nStar; i++) {
  const q = S.star[i % 22];
  const ang = q.a + K.t * .12 * q.w + (i % 2 ? -1 : 1) * K.t * .03;
  const rr = q.r * (120 + 34 * Math.sin(K.t * .35 + q.o)) * s;
  const tw = .4 + .6 * Math.abs(Math.sin(K.t * 1.0 + q.o * 3));
  const hh = st === 'blueprint' ? (H + 6) % 360 : (i % 5 === 0 ? 40 : 200);
  fill(hh, i % 5 === 0 ? 40 : 10, 100, Math.min(70, tw * (10 + 14 * K.swell) + S.tre * 46));
  circle(ax + Math.cos(ang) * rr, ay - 150 * s + Math.sin(ang) * rr * .6, q.sz * (1.3 + 1.5 * S.tre) * s);
}
blendMode(BLEND);
